def test_three_views_with_fewer_units_rearm_the_phantom(monkeypatch):
    mem = memory()
    record = []
    monkeypatch.setattr(m, '_record', lambda *a, **k: record.append(k) or None)
    for _ in range(m.UNVERIFIED_LAUNCH_LIMIT):
        m._settle_unverified_launches(mem, [[141, 85, 147, 90]])
    assert mem['world']['launched_orders'] == {}
    assert mem['plan']['orders'] == {'A:1': 'pending', 'A:2': 'pending'}
    assert any(r.get('decision') == 'sortie_unverified_rearmed' or True for r in record)


def test_a_launch_with_a_march_record_is_kept(monkeypatch):
    mem = memory()
    mem['world']['sorties'] = {'A:1': {'status': 'en_route'}}
    monkeypatch.setattr(m, '_record', lambda *a, **k: None)
