def test_enough_units_resets_the_watch(monkeypatch):
    mem = memory()
    monkeypatch.setattr(m, '_record', lambda *a, **k: None)
    m._settle_unverified_launches(mem, [[1, 1, 2, 2]])
    assert mem.get('launch_unverified')
